insert into t_sys_model_service_provider(ID,PROVIDER_NAME,PROVIDER_NAME_EN,DESCRIPTION,DESCRIPTION_EN,TAGS,PROVIDER_URL,CREATED_DATE,LAST_UPDATED_DATE,LOGO,STATUS,priority) values ('100','','','ModelArts Standard是面向AI开发者的一站式开发平台，提供了简洁易用的管理控制台，包含数据管理、开发环境、模型训练、模型管理、部署上线等端到端的AI开发工具链。','ModelArts Studio (MaaS) and ModelArts Standard constitute an integrated, developer-centric AI platform, delivering a comprehensive, end-to-end AI development toolchain. The platform features an intuitive and streamlined management console, offering robust capabilities across data management, development environments, model training, model lifecycle management, and production deployment. Designed for AI practitioners, it enables efficient, scalable, and reproducible model development and delivery.','中文,英文,文本对话,图像理解','','1753675200000','1753675200000','data:image/png;base64,','created','0');
